import glob

def parse_v2(s):
    return Decimal(s.strip())

def parse_v1(s):
    return Decimal(s.strip().replace(" ", "").replace(".", "").replace(",", "."))

for path in sorted(glob.glob("feeds/*/*.csv")):
    lines = open(path).read().splitlines()
    fmt = [l for l in lines if "format:" in l][0].split(":")[1].strip()
    sep = "|" if "|" in lines[3] else ";"
    tot = Decimal(0)
    n = 0
    for l in lines:
        if not l or l.startswith("#") or l.startswith("date"):
            continue
        d, a, amt = l.split(sep)
        tot += parse_v1(amt) if fmt == "v1" else parse_v2(amt)
        n += 1
    print(path, fmt, n, "rows ->", tot)
